import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, float } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'journal-card-1-label';
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const width = 1.6;
  const height = (320 / 512) * width;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial();

  let map = null;
  try {
    map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
    if (map) {
      map.colorSpace = THREE.SRGBColorSpace;
      map.wrapS = THREE.ClampToEdgeWrapping;
      map.wrapT = THREE.ClampToEdgeWrapping;
    }
  } catch (e) {
    map = null;
  }

  const inkColor = new THREE.Color(colors.ink);
  const surfaceColor = new THREE.Color(colors.surface);

  if (map) {
    const texNode = texture(map, uv());
    const gradient = mix(
      vec4(surfaceColor.r, surfaceColor.g, surfaceColor.b, 1.0),
      vec4(inkColor.r, inkColor.g, inkColor.b, 1.0),
      uv().y
    );
    material.colorNode = mix(gradient, texNode, float(0.55));
  } else {
    material.colorNode = mix(
      vec4(surfaceColor.r, surfaceColor.g, surfaceColor.b, 1.0),
      vec4(inkColor.r, inkColor.g, inkColor.b, 1.0),
      uv().y
    );
  }

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'journal-card-1-label-plane';
  group.add(plane);

  let textMesh = null;
  try {
    textMesh = createTextMesh({
      text: config?.textContent?.[0]?.value || 'Journal 1',
      fontAtlas: ctx.fontAtlas,
      font: 'Lora',
      weight: 400,
      size: 0.34,
      color: colors.paper,
      align: 'left',
    });
    if (textMesh) {
      textMesh.position.set(-width / 2 + 0.12, height / 2 - 0.22, 0.01);
      group.add(textMesh);
    }
  } catch (e) {
    textMesh = null;
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) {
        if (Array.isArray(textMesh.material)) {
          textMesh.material.forEach((m) => m.dispose());
        } else {
          textMesh.material.dispose();
        }
      }
    }
  };

  return group;
}
